import org.apache.spark.sql.{DataFrame, Encoders}
import java.time.LocalDate

object Solution {
  final case class Ev(user: String, day: String)
  final case class Streak(user: String, streak: Long)

  def solve(df: DataFrame): DataFrame = {
    df.select("user", "day")
      .as[Ev](Encoders.product[Ev])
      .groupByKey(_.user)(Encoders.STRING)
      .mapGroups { (user, events) =>
        // 用 epochDay 排序：LocalDate 没有隐式 Ordering，且按天差判断跨年边界才安全
        val days = events.map(e => LocalDate.parse(e.day).toEpochDay).toSeq.distinct.sorted
        var best = 0L
        var run = 0L
        var prev = Long.MinValue
        days.foreach { d =>
          run = if (d == prev + 1L) run + 1L else 1L
          if (run > best) best = run
          prev = d
        }
        Streak(user, if (days.isEmpty) 0L else best)
      }(Encoders.product[Streak])
      .orderBy("user")
      .toDF("user", "streak")
  }
}

